using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ShopSetup", menuName = "Data/BattleSceneSetups/ShopSetup", order = 0)]
public class ShopSetup : BattleSceneSetup
{
	[SerializeField]
	private VoidEvent OnDisableTurnCounterText;

	public override void SetupScene()
	{
		base.SetupScene();
		OnDisableTurnCounterText.Raise();
		ReferenceSingleton<GameStateManager>.Instance.SetPlayerRewardStateState();
		mapHandler.CurrentReward.GetReward();
	}

	public override void PlayBGM()
	{
		if (!mapHandler.IsOnAstreasHeart)
		{
			OnPlayBGM.Raise();
		}
	}
}
